using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ExternalApiTool
{
    [McpServerTool, Description("Fetches data from an external API for the given resource ID.")]
    public static async Task<string> FetchData(
        IHttpClientFactory httpClientFactory,
        [Description("The resource ID to look up")] string resourceId,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("ExternalApi");

        var response = await client.GetAsync($"resources/{resourceId}", cancellationToken);
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        return content;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompt
{
    [McpServerPrompt, Description("Generates a prompt to summarize the provided text.")]
    public static IList<McpServerPromptMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        var systemInstruction = style switch
        {
            "detailed" => "Provide a comprehensive summary covering all key points.",
            "bullet-points" => "Summarize the text as a concise bullet-point list.",
            _ => "Provide a brief one-paragraph summary of the key points."
        };

        return
        [
            new McpServerPromptMessage
            {
                Role = "assistant",
                Content = new() { Type = "text", Text = systemInstruction }
            },
            new McpServerPromptMessage
            {
                Role = "user",
                Content = new() { Type = "text", Text = $"Please summarize the following text:\n\n{text}" }
            }
        ];
    }
}

